import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import {
    onChatChanged,
    onGenerationStopped,
    memuGenerationInterceptor,
    onMessageEdited,
    onMessageReceived,
    onMessageSwiped,
    onMessageDeleted,
    onUserMessageSent,
} from 'memory/exports';
import { st, pruneStalePerSoulEntries } from './utils/context-extra';
import { MemuTaskStatus } from './utils/types';
import { MEMU_LOCAL_STORAGE_OVERRIDE_SUMMARIZER, MEMU_LOCAL_STORAGE_IMPORT_LOREBOOKS, MEMU_LOCAL_STORAGE_MENTAL_HEALTH_ADDON } from './utils/consts';
import { info, warn, error as logError } from './utils/log';
import { startInspectObserver } from './ui/inspect-panel';
import { installAutomationHooks } from './ui/automation-hooks';
import { currentScope, isMemuActive, onCharacterDuplicated, onCharacterRenamed } from './memory/utils';

(globalThis as any).memuGenerationInterceptor = memuGenerationInterceptor;

function installHooksWithRetry(): void {
    const w = window as any;
    if (w.__memuHooksInstalled) return;

    function tryInstallOnce(): boolean {
        // Background hooks (must run even when Settings UI isn't open)
        // Some ST builds initialize eventSource late; retry briefly instead of failing forever.
        if (!st?.eventSource?.on) return false;
        try {
            st.eventSource.on(st.event_types.GENERATION_STOPPED, onGenerationStopped);
            st.eventSource.on(st.event_types.CHAT_CHANGED, onChatChanged);
            st.eventSource.on(st.event_types.MESSAGE_SENT, onUserMessageSent);
            st.eventSource.on(st.event_types.CHARACTER_MESSAGE_RENDERED, onMessageReceived);
            st.eventSource.on(st.event_types.MESSAGE_EDITED, onMessageEdited);
            st.eventSource.on(st.event_types.MESSAGE_SWIPED, onMessageSwiped);
            st.eventSource.on(st.event_types.MESSAGE_DELETED, onMessageDeleted);
            st.eventSource.on(st.event_types.CHARACTER_DUPLICATED, onCharacterDuplicated);
            st.eventSource.on(st.event_types.CHARACTER_RENAMED, onCharacterRenamed);
            return true;
        } catch (e) {
            logError("hooks install failed", e);
            return false;
        }
    }

    if (tryInstallOnce()) {
        w.__memuHooksInstalled = true;
        try { onChatChanged(); } catch { }
        return;
    }

    let attempts = 0;
    const timer = window.setInterval(() => {
        if (w.__memuHooksInstalled) {
            window.clearInterval(timer);
            return;
        }
        attempts += 1;
        if (tryInstallOnce()) {
            w.__memuHooksInstalled = true;
            window.clearInterval(timer);
            try { onChatChanged(); } catch { }
            return;
        }
        if (attempts >= 40) {
            window.clearInterval(timer);
            warn("hooks not installed after retries (eventSource unavailable)");
        }
    }, 250);
}

installHooksWithRetry();

let mounted = false;

function installChatOptionResetCursor(): void {
    const OPTION_ID = 'option_memu_memorize_from_beginning';
    const DISABLED_OPACITY = '0.5';
    let actionEl: HTMLAnchorElement | null = null;
    let disabledPollTimer: number | null = null;

    function isMemorizeActive(): boolean {
        const summary: any = (st.getContext() as any)?.chatMetadata?.memuExtras?.summary;
        if (!summary) return false;
        const status = summary.summaryTaskStatus;
        return status === MemuTaskStatus.PENDING || status === MemuTaskStatus.PROCESSING;
    }

    function applyDisabledState(): void {
        if (!actionEl) return;
        const disabled = isMemorizeActive();
        actionEl.style.pointerEvents = disabled ? 'none' : '';
        actionEl.style.opacity = disabled ? DISABLED_OPACITY : '';
        actionEl.style.cursor = disabled ? 'not-allowed' : '';
        if (disabled) {
            actionEl.setAttribute('aria-disabled', 'true');
            actionEl.title = 'memU is already memorizing this chat';
        } else {
            actionEl.removeAttribute('aria-disabled');
            actionEl.title = '';
        }
    }

    function ensureDisabledPoll(): void {
        if (disabledPollTimer !== null) return;
        disabledPollTimer = window.setInterval(() => {
            applyDisabledState();
        }, 500);
    }

    async function resetCursor(): Promise<void> {
        try {
            if (!(await isMemuActive())) return;
            const scope = currentScope();
            const { st } = await import('./utils/context-extra');
            const { doSummary } = await import('./memory/memorize');
            if (!(await isMemuActive()) || currentScope() !== scope) return;

            const ctx: any = st.getContext() as any;
            const chat: any[] = Array.isArray(ctx?.chat) ? ctx.chat : [];
            if (chat.length === 0) {
                info("memorize from beginning skipped: empty chat");
                return;
            }

            // Force a full digest immediately (do not require leaving/re-entering the chat).
            await doSummary(0, chat.length - 1, { force: true });
        } catch (e) {
            logError("reset failed", e);
        }
    }


    function tryInstall(): boolean {
        const options = document.querySelector('#options .options-content') as HTMLElement | null;
        if (!options) return false;
        const existing = document.getElementById(OPTION_ID) as HTMLAnchorElement | null;
        if (existing) {
            actionEl = existing;
            applyDisabledState();
            return true;
        }

        const anchor = document.createElement('a');
        anchor.id = OPTION_ID;
        const icon = document.createElement('i');
        icon.className = 'fa-lg fa-solid fa-rotate-left';
        const label = document.createElement('span');
        label.textContent = 'Re-memorize chat';
        anchor.appendChild(icon);
        anchor.appendChild(label);

        anchor.addEventListener('click', async (ev) => {
            ev.preventDefault();
            if (!(await isMemuActive())) return;
            if (isMemorizeActive()) return;
            const { st } = await import('./utils/context-extra');
            const ctx: any = st.getContext() as any;
            if (!ctx?.characterId && !ctx?.groupId) return;
            const chat: any[] = Array.isArray(ctx?.chat) ? ctx.chat : [];
            if (chat.length === 0) return;
            if (!window.confirm('Warning!!! This option is for developer testing. This will rename your current database and start a new one. Other SillyTavern chats will not be included in the new database. Other client chats, such as WhatsApp chats, will not be included.')) return;
            await resetCursor();

            // Close the options menu (if open) to match built-in actions.
            const menu = document.getElementById('options') as HTMLElement | null;
            if (menu) menu.style.display = 'none';
        });

        // Place it near other chat-level actions.
        const after = document.getElementById('option_select_chat');
        if (after && after.parentElement === options) {
            options.insertBefore(anchor, after.nextSibling);
            actionEl = anchor;
            applyDisabledState();
            return true;
        }

        options.appendChild(anchor);
        actionEl = anchor;
        applyDisabledState();
        return true;
    }

    ensureDisabledPoll();
    if (tryInstall()) return;

    // options menu is present late in some ST builds; retry briefly.
    let attempts = 0;
    const timer = window.setInterval(() => {
        attempts += 1;
        if (tryInstall() || attempts >= 40) window.clearInterval(timer);
    }, 250);
}

function tryMount(): boolean {
    if (mounted) return true;

    // ST versions differ: some use extensions_settings2, others use extensions_settings
    const rootContainer =
        document.getElementById('extensions_settings2') ||
        document.getElementById('extensions_settings');

    if (!rootContainer) return false;

    const rootElement = document.createElement('div');
    rootElement.className = 'memu-ext-settings-root';
    rootContainer.appendChild(rootElement);

    const root = ReactDOM.createRoot(rootElement);
    root.render(
        <React.StrictMode>
            <App />
        </React.StrictMode>
    );

    mounted = true;
    return true;
}

// Mount immediately if possible.
if (!tryMount()) {
    // Some ST builds create the settings container later; retry briefly without failing the extension.
    let attempts = 0;
    const timer = window.setInterval(() => {
        attempts += 1;
        if (tryMount() || attempts >= 40) {
            window.clearInterval(timer);
            if (!mounted) {
                warn("UI not mounted after retries (settings container missing)");
            }
        }
    }, 250);
}

installChatOptionResetCursor();
startInspectObserver();
installAutomationHooks();
pruneStalePerSoulEntries([
    MEMU_LOCAL_STORAGE_OVERRIDE_SUMMARIZER,
    MEMU_LOCAL_STORAGE_IMPORT_LOREBOOKS,
    MEMU_LOCAL_STORAGE_MENTAL_HEALTH_ADDON,
]);
